package ai.graine.inapp

import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File
import java.util.TreeMap

/**
 * EVERY ANSWER HERE WAS PRODUCED BY THE REACT NATIVE SDK'S OWN CODE.
 *
 * sdk/contract/rn-parity.json is generated by sdk/contract/generate-rn-parity.mjs,
 * which imports the RN SDK's built dist and runs its pure rules over a fixed
 * set of inputs. Every native SDK reads that one file and must reproduce each
 * answer exactly — a hand-written expected value would only be a second
 * opinion about what the first one says.
 */
class RnParityTest {
    private val fx: JSONObject by lazy {
        var dir: File? = File("").absoluteFile
        while (dir != null && !File(dir, "sdk/contract/rn-parity.json").exists() && !File(dir, "contract/rn-parity.json").exists()) {
            dir = dir.parentFile
        }
        val f = listOf(File(dir, "sdk/contract/rn-parity.json"), File(dir, "contract/rn-parity.json")).firstOrNull { it.exists() }
            ?: error("sdk/contract/rn-parity.json missing — run sdk/contract/generate-rn-parity.mjs")
        JSONObject(f.readText())
    }

    private fun cases(name: String): List<JSONObject> = fx.getJSONArray(name).let { a -> (0 until a.length()).map { a.getJSONObject(it) } }

    /** JSON and Kotlin values in one comparable shape: numbers as doubles, maps sorted, JSON null as null. */
    private fun canon(v: Any?): Any? = when {
        v == null || v == JSONObject.NULL -> null
        v is JSONObject -> TreeMap<String, Any?>().also { m -> v.keys().forEach { k -> m[k] = canon(v.opt(k)) } }
        v is JSONArray -> (0 until v.length()).map { canon(v.opt(it)) }
        v is Map<*, *> -> TreeMap<String, Any?>().also { m -> v.forEach { (k, x) -> m[k.toString()] = canon(x) } }
        v is Iterable<*> -> v.map { canon(it) }
        v is Number -> v.toDouble()
        else -> v
    }

    private fun mapOfNonNull(vararg pairs: Pair<String, Any?>): Map<String, Any?> = pairs.filter { it.second != null }.toMap()

    private fun styleMap(s: WidgetStyle) = mapOfNonNull(
        "preset" to s.preset, "imageSize" to s.imageSize, "density" to s.density, "button" to s.button, "facts" to s.facts,
        "columns" to s.columns, "surface" to s.surface, "radius" to s.radius, "accent" to s.accent, "platform" to s.platform,
        "select" to s.select, "maxSelect" to s.maxSelect,
    )

    private fun lookMap(l: WidgetLook) = mapOfNonNull(
        "preset" to l.preset, "imageSize" to l.imageSize, "density" to l.density, "button" to l.button, "facts" to l.facts,
        "columns" to l.columns, "surface" to l.surface, "radius" to l.radius, "accent" to l.accent, "platform" to l.platform,
        "select" to l.select, "maxSelect" to l.maxSelect,
    )

    private fun str(o: JSONObject, k: String): String? = if (o.isNull(k)) null else o.getString(k)

    @Test fun normalisesAWidgetStyleExactlyAsReactNativeDoes() {
        for (c in cases("widgetStyle")) {
            assertEquals("input ${c.opt("input")}", canon(c.get("output")), canon(styleMap(Widgets.normaliseStyle(c.opt("input")))))
        }
    }

    @Test fun resolvesTheSameLook() {
        for (c in cases("widgetLook")) {
            val look = Widgets.resolveLook(Widgets.normaliseStyle(c.opt("style")), str(c, "kind"))
            assertEquals("style ${c.opt("style")} kind ${c.opt("kind")}", canon(c.get("output")), canon(lookMap(look)))
        }
    }

    @Test fun putsEachKindOnTheSameSurface() {
        for (c in cases("widgetSurface")) assertEquals("kind ${c.opt("kind")}", c.getString("output"), Widgets.surface(str(c, "kind")))
    }

    @Test fun followsThePhonesGrammarTheSameWay() {
        for (c in cases("platform")) {
            assertEquals(c.toString(), c.getString("output"), Widgets.resolvePlatform(str(c, "platform"), str(c, "os"), str(c, "manufacturer")))
        }
        val g = fx.getJSONObject("grammar")
        for (name in listOf("ios", "material", "oneui")) {
            val want = g.getJSONObject(name)
            val got = Widgets.GRAMMAR.getValue(name)
            val mine = mapOf(
                "radius" to got.radius, "chipRadius" to got.chipRadius, "buttonRadius" to got.buttonRadius, "pillButtons" to got.pillButtons,
                "separatorInset" to got.separatorInset, "grabber" to mapOf("width" to got.grabberWidth, "height" to got.grabberHeight),
                "titleWeight" to got.titleWeight.toString(), "padBoost" to got.padBoost, "chipOutlined" to got.chipOutlined,
            )
            assertEquals(name, canon(want), canon(mine))
        }
    }

    @Test fun allowlistsATapsActionTheSameWay() {
        for (c in cases("selectAction")) {
            val got = Widgets.normaliseSelectAction(c.opt("input"))
            val want = c.getJSONObject("output")
            val input = c.opt("input")
            val argCount = ((input as? JSONObject)?.opt("args") as? JSONObject)?.length() ?: 0
            if (argCount > Widgets.SELECT_ARG_MAX) {
                // Which ten survive depends on key order, and the JVM's org.json does not keep it.
                // Android's does; the count and the cut are what the rule is.
                assertEquals(want.getJSONObject("args").length(), got.args!!.size)
                assertTrue(got.args!!.values.all { it.length == Widgets.SELECT_VALUE_MAX })
                assertEquals(want.getString("action"), got.action)
                continue
            }
            val mine = mapOfNonNull("action" to got.action, "path" to got.path, "args" to got.args, "say" to got.say)
            assertEquals("input $input", canon(want), canon(mine))
        }
    }

    @Test fun runsTheSameActionForATap() {
        for (c in cases("selectCall")) {
            val call = Widgets.selectCall(Widgets.normaliseSelectAction(c.opt("onSelect")), Js.plain(c.getJSONObject("item")) as Map<String, Any?>)
            val want = c.opt("output")
            if (Js.nullish(want)) { assertNull(c.toString(), call); continue }
            assertEquals(c.toString(), canon(want), canon(mapOf("name" to call!!.name, "args" to call.args)))
        }
        for (c in cases("template")) {
            @Suppress("UNCHECKED_CAST")
            val item = Js.plain(c.getJSONObject("item")) as Map<String, Any?>
            assertEquals(c.toString(), c.getString("output"), Widgets.fillSelectTemplate(c.getString("template"), item))
        }
    }

    @Test fun namesSeveralChoicesInTheSameSentence() {
        for (c in cases("manySummary")) {
            val titles = c.getJSONArray("titles").let { a -> (0 until a.length()).map { a.getString(it) } }
            assertEquals(c.getString("output"), Widgets.manySummary(titles, c.getString("verb")))
        }
    }

    @Test fun resolvesTheSamePictures() {
        for (c in cases("widgetImages")) {
            val got = Widgets.resolveImages(c.getJSONObject("data"), c.getString("baseUrl"))
            assertEquals(c.toString(), canon(c.get("output")), canon(got))
        }
    }

    @Test fun resolvesTheSameLoader() {
        for (c in cases("loaderStyle")) {
            val n = Loaders.normalise(c.opt("input"))
            val text = n.text?.let { t -> mapOfNonNull("connecting" to t.connecting, "reconnecting" to t.reconnecting, "thinking" to t.thinking, "component" to t.component) }
            val normalised = mapOfNonNull("kind" to n.kind, "color" to n.color, "size" to n.size, "speed" to n.speed, "text" to text, "skeleton" to n.skeleton)
            assertEquals("normalise ${c.opt("input")}", canon(c.get("normalised")), canon(normalised))
            val r = Loaders.resolve(c.opt("input"))
            val resolved = mapOf(
                "kind" to r.kind, "color" to r.color, "px" to r.px, "periodMs" to r.periodMs, "skeleton" to r.skeleton,
                "text" to mapOf("connecting" to r.text.connecting, "reconnecting" to r.text.reconnecting, "thinking" to r.text.thinking, "component" to r.text.component),
            )
            assertEquals("resolve ${c.opt("input")}", canon(c.get("resolved")), canon(resolved))
        }
    }

    private fun bounds(o: JSONObject) = Placement.Bounds(
        windowHeight = o.getDouble("windowHeight"), baseBottom = o.getDouble("baseBottom"), barHeight = o.getDouble("barHeight"),
        topMargin = if (o.has("topMargin")) o.getDouble("topMargin") else 48.0,
    )

    @Test fun placesTheBarWithTheSameArithmetic() {
        for (c in cases("clampOffset")) {
            assertEquals(c.toString(), c.getInt("output"), Placement.clampOffset(c.getDouble("offset"), bounds(c.getJSONObject("bounds"))))
        }
        for (c in cases("offsetDuringDrag")) {
            assertEquals(c.toString(), c.getInt("output"), Placement.offsetDuringDrag(c.getDouble("start"), c.getDouble("dy"), bounds(c.getJSONObject("bounds"))))
        }
        for (c in cases("isTap")) assertEquals(c.toString(), c.getBoolean("output"), Placement.isTap(c.getDouble("dx"), c.getDouble("dy")))
        for (c in cases("liftFor")) assertEquals(c.toString(), c.getInt("output"), KeyboardLift.liftFor(c.getDouble("keyboard"), c.getDouble("shrink")))
    }

    @Test fun translatesTheDashboardsAppearanceTheSameWay() {
        for (c in cases("appearance")) {
            val f = c.getJSONObject("fallback")
            val a = Appearance.resolve(
                appearance = c.opt("appearance") as? JSONObject,
                accent = f.getString("accent"),
                heading = f.getString("heading"),
                radius = if (f.has("radius")) f.getDouble("radius") else null,
                maxRadius = if (f.has("maxRadius")) f.getDouble("maxRadius") else null,
                origin = if (f.has("origin")) f.getString("origin") else null,
            )
            assertEquals(c.toString(), canon(c.get("output")),
                canon(mapOf("accent" to a.accent, "heading" to a.heading, "logoUrl" to a.logoUrl, "logoPlate" to a.logoPlate.wire, "radius" to a.radius)))
        }
        // Not a vacuous pass: the file carries both plates, and junk that must fall back to the accent.
        val plates = cases("appearance").map { it.getJSONObject("output").getString("logoPlate") }
        assertTrue("rn-parity has no white plate", "white" in plates)
        assertTrue("rn-parity has no accent plate", "accent" in plates)
        val junk = cases("appearance").filter { (it.opt("appearance") as? JSONObject)?.let { a -> a.has("logoPlate") && a.opt("logoPlate") != "white" && a.opt("logoPlate") != "accent" } == true }
        assertTrue("rn-parity has no junk plate (\"WHITE\", 1)", junk.size >= 2)
        for (c in cases("palette")) {
            val p = Appearance.palette(c.opt("appearance") as? JSONObject, deviceDark = str(c, "scheme") == "dark", accent = c.getString("accent"))
            val mine = mapOf("surface" to p.surface, "border" to p.border, "text" to p.text, "muted" to p.muted, "onAccent" to p.onAccent, "mode" to p.mode)
            assertEquals(c.toString(), canon(c.get("output")), canon(mine))
        }
    }

    private fun screenOf(o: Any?): GraineScreen? {
        if (o !is JSONObject) return null
        val fields = (o.optJSONArray("fields") ?: JSONArray()).let { a ->
            (0 until a.length()).map { i ->
                val f = a.getJSONObject(i)
                GraineField(
                    name = f.getString("name"),
                    label = str(f, "label").takeIf { f.has("label") },
                    value = if (f.has("value")) str(f, "value") else null,
                    status = if (f.has("status")) GraineField.Status.values().first { it.wire == f.getString("status") } else null,
                    error = if (f.has("error")) str(f, "error") else null,
                    optional = f.optBoolean("optional", false),
                )
            }
        }
        return GraineScreen(screen = o.getString("screen"), title = if (o.has("title")) o.getString("title") else null, fields = fields)
    }

    @Test fun noticesAStalledCustomerAtTheSameMomentWithTheSameWords() {
        for (script in cases("frictionIdle")) {
            val layers = script.getJSONArray("config").let { a -> (0 until a.length()).map { FrictionConfig.fromJson(a.getJSONObject(it)) } }
            // The RN rule itself: no outstanding-field gate, no call gate.
            val d = FrictionDetector(Friction.resolve(*layers.toTypedArray(), FrictionConfig(requireOutstandingField = false)))
            val ops = script.getJSONArray("ops")
            val want = script.getJSONArray("output")
            for (i in 0 until ops.length()) {
                val op = ops.getJSONArray(i)
                val got: Any? = when (op.getString(0)) {
                    "screen" -> { d.onScreen(screenOf(op.opt(1)), op.getLong(2)); null }
                    "interaction" -> { d.onInteraction(op.getLong(1)); null }
                    "dueIn" -> d.idleDueIn(op.getLong(1))
                    "idle" -> d.onIdle(op.getLong(1))?.let { s ->
                        mapOf("name" to s.name, "screen" to s.screen, "detail" to s.detail, "data" to s.data,
                            "cooldown_seconds" to s.cooldownSeconds, "max_per_session" to s.maxPerSession)
                    }
                    else -> error("unknown op")
                }
                assertEquals("script ${script.getJSONArray("config")} op #$i $op", canon(want.opt(i)), canon(got))
            }
        }
    }
}
